{"file_path":"src/cli.js","content":"#!/usr/bin/env node
/**
 * The command. `node src/cli.js values` prints the value of every cell in the
 * sheet read from stdin, and `node src/cli.js deps` prints the cells
 * each one reads.
 */

import { readFileSync } from 'fs'
import { Parser } from './parser.js'
import { Evaluator } from './evaluator.js'

const args = process.argv.slice(2)

if (args.length !== 1 || (args[0] !== 'values' && args[0] !== 'deps')) {
  process.stderr.write('error: usage: cli.js values|deps\n')
  process.exit(2)
}

const mode = args[0]

// Read stdin
let input = ''
try {
  input = readFileSync(0, 'utf8')
} catch (e) {
  // Handle case where stdin is empty or not available
  input = ''
}

const parser = new Parser()
const cells = parser.parse(input)

if (!cells.success) {
  process.stderr.write(cells.error)
  process.exit(2)
}

const evaluator = new Evaluator(cells.cells)
const results = evaluator.evaluate(mode)

if (mode === 'values') {
  // Sort by column then row and print
  const sorted = Array.from(results.entries()).sort(([addr1], [addr2]) => {
    const col1 = addr1.match(/[A-Z]+/)[0]
    const row1 = parseInt(addr1.match(/\d+/)[0])
    const col2 = addr2.match(/[A-Z]+/)[0]
    const row2 = parseInt(addr2.match(/\d+/)[0])

    if (col1 !== col2) {
      return col1.localeCompare(col2)
    }
    return row1 - row2
  })

  for (const [addr, value] of sorted) {
    process.stdout.write(`${addr}=${value}\n`)
  }
} else {
  // deps mode
  const sorted = Array.from(results.entries()).sort(([addr1], [addr2]) => {
    const col1 = addr1.match(/[A-Z]+/)[0]
    const row1 = parseInt(addr1.match(/\d+/)[0])
    const col2 = addr2.match(/[A-Z]+/)[0]
    const row2 = parseInt(addr2.match(/\d+/)[0])

    if (col1 !== col2) {
      return col1.localeCompare(col2)
    }
    return row1 - row2
  })

  for (const [addr, deps] of sorted) {
    process.stdout.write(`${addr}:`)
    for (const dep of deps) {
      process.stdout.write(` ${dep}`)
    }
    process.stdout.write('\n')
  }
}

process.exit(0)
"}

