{"file_path":"src/parser.js","content":"/**
 * Parser for the input format
 */

export class Parser {
  parse(input) {
    const lines = input.split('\n')
    // Drop the empty tail a trailing newline leaves
    if (lines.length > 0 && lines[lines.length - 1] === '') {
      lines.pop()
    }

    const cells = new Map()

    for (let lineNum = 0; lineNum < lines.length; lineNum++) {
      let line = lines[lineNum]

      // Strip leading spaces and tabs
      line = line.replace(/^[ \t]+/, '')

      // Ignore empty lines or lines starting with #
      if (line === '' || line.startsWith('#')) {
        continue
      }

      // Parse address and content
      const match = line.match(/^([A-Za-z1-9][A-Za-z0-9]*)/)
      if (!match) {
        return {
          success: false,
          error: `error: line ${lineNum + 1}: invalid cell address\n`
        }
      }

      const address = match[1].toUpperCase()

      // Validate address
      const addrValidation = this.validateAddress(address)
      if (!addrValidation.valid) {
        return {
          success: false,
          error: `error: line ${lineNum + 1}: invalid cell address ${address}\n`
        }
      }

      // Check for duplicate
      if (cells.has(address)) {
        return {
          success: false,
          error: `error: line ${lineNum + 1}: cell ${address} is declared twice\n`
        }
      }

      // Extract content
      const contentStart = match[0].length
      let content = line.substring(contentStart)

      // Skip one run of spaces and tabs
      content = content.replace(/^[ \t]+/, '')

      cells.set(address, content)
    }

    return {
      success: true,
      cells
    }
  }

  validateAddress(address) {
    // Address is 1-2 letters (columns A-Z, AA-ZZ) + 1-3 digits (rows 1-999)
    const match = address.match(/^([A-Z]{1,2})(\d{1,3})$/)
    if (!match) {
      return { valid: false }
    }

    const [, col, row] = match
    const rowNum = parseInt(row)

    // Row must be at least 1
    if (rowNum < 1 || rowNum > 999) {
      return { valid: false }
    }

    // Column validation: A-Z or AA-ZZ
    if (col.length === 1) {
      // Single letter: A-Z
      if (!/^[A-Z]$/.test(col)) {
        return { valid: false }
      }
    } else if (col.length === 2) {
      // Two letters: AA-ZZ
      if (!/^[A-Z]{2}$/.test(col)) {
        return { valid: false }
      }
    } else {
      return { valid: false }
    }

    return { valid: true }
  }
}
"}

