    const fromRow = parseInt(fromMatch[2])
    const toCol = toMatch[1]
    const toRow = parseInt(toMatch[2])

    const colStart = this.colToNum(fromCol)
    const colEnd = this.colToNum(toCol)
    const rowStart = Math.min(fromRow, toRow)
    const rowEnd = Math.max(fromRow, toRow)

