export class Evaluator {
  constructor(cells) {
    this.cellsMap = cells
    this.evaluatedCache = new Map()
    this.evaluationInProgress = new Set()
  }

  evaluate(mode) {
    const results = new Map()

    for (const [address, content] of this.cellsMap) {
      if (mode === 'values') {
        const value = this.evaluateCell(address)
        results.set(address, this.formatValue(value))
      } else {
        // deps mode
        const deps = this.getDependencies(address)
        results.set(address, deps)
      }
    }

    return results
  }

  evaluateCell(address) {
    // Check if already evaluated
    if (this.evaluatedCache.has(address)) {
      return this.evaluatedCache.get(address)
    }

    // Check for cycle
    if (this.evaluationInProgress.has(address)) {
      return { type: 'error', value: '#CYCLE!' }
    }

    this.evaluationInProgress.add(address)

    const content = this.cellsMap.get(address)
    let result

    if (content === undefined || content === '') {
      result = { type: 'number', value: 0 }
    } else if (content.startsWith('=')) {
      // It's a formula
      const formula = content.substring(1)
      const parser = new FormulaParser(formula, this)
      result = parser.parse()
    } else {
      // It's a literal
      result = this.parseLiteral(content)
    }

    this.evaluationInProgress.delete(address)
    this.evaluatedCache.set(address, result)
    return result
  }

  getDependencies(address) {
    const content = this.cellsMap.get(address)
    if (!content || !content.startsWith('=')) {
      return []
    }

    const formula = content.substring(1)
    const parser = new FormulaParser(formula, this)
    const deps = parser.parseDeps()

    // Sort by column then row
    return deps.sort((a, b) => {
      const col1 = a.match(/[A-Z]+/)[0]
      const row1 = parseInt(a.match(/\d+/)[0])
      const col2 = b.match(/[A-Z]+/)[0]
      const row2 = parseInt(b.match(/\d+/)[0])

      if (col1 !== col2) {
        return col1.localeCompare(col2)
      }
      return row1 - row2
    })
  }

  parseLiteral(content) {
    // Check if it's an error token
    if (['#DIV/0!', '#REF!', '#VALUE!', '#CYCLE!', '#NAME?', '#ERR!'].includes(content)) {
      return { type: 'error', value: content }
    }

    // Check if it's a boolean
    if (content === 'TRUE') {
      return { type: 'boolean', value: true }
    }
    if (content === 'FALSE') {
      return { type: 'boolean', value: false }
    }

    // Check if it's a number
    const numberMatch = content.match(/^-?\d+(?:\.\d+)?$/)
    if (numberMatch) {
      return { type: 'number', value: parseFloat(content) }
    }

    // Otherwise it's text
    return { type: 'text', value: content }
  }

  formatValue(val) {
    if (val.type === 'error') {
      return val.value
    }
    if (val.type === 'boolean') {
      return val.value ? 'TRUE' : 'FALSE'
    }
    if (val.type === 'number') {
      // Round to 10 significant digits
      const str = val.value.toPrecision(10)
      // Remove trailing zeros and decimal point if not needed
      return parseFloat(str).toString()
    }
    if (val.type === 'text') {
      return val.value
    }
    return 'unknown'
  }
}

class FormulaParser {
  constructor(formula, evaluator) {
    this.formula = formula
    this.evaluator = evaluator
    this.pos = 0
    this.tokens = this.tokenize()
    this.tokenIndex = 0
    this.deps = new Set()
  }

  tokenize() {
    const tokens = []
    let i = 0
    while (i < this.formula.length) {
      const c = this.formula[i]

      // Skip spaces and tabs
      if (c === ' ' || c === '\t') {
        i++
        continue
      }

      // Numbers
      if (/\d/.test(c)) {
        let num = ''
        while (i < this.formula.length && (/\d/.test(this.formula[i]) || this.formula[i] === '.')) {
          num += this.formula[i]
          i++
        }
        tokens.push({ type: 'number', value: parseFloat(num) })
        continue
      }

      // Operators
      if ('+-*/^=<>(),:'.includes(c)) {
        if (c === '<' && i + 1 < this.formula.length && this.formula[i + 1] === '=') {
          tokens.push({ type: 'operator', value: '<=' })
          i += 2
        } else if (c === '>' && i + 1 < this.formula.length && this.formula[i + 1] === '=') {
          tokens.push({ type: 'operator', value: '>=' })
          i += 2
        } else if (c === '<' && i + 1 < this.formula.length && this.formula[i + 1] === '>') {
          tokens.push({ type: 'operator', value: '<>' })
          i += 2
        } else {
          tokens.push({ type: 'operator', value: c })
          i++
        }
        continue
      }

      // Names (cell addresses, booleans, function names)
      if (/[A-Za-z]/.test(c)) {
        let name = ''
        while (i < this.formula.length && /[A-Za-z0-9]/.test(this.formula[i])) {
          name += this.formula[i]
          i++
        }
        name = name.toUpperCase()

        // Check for boolean values
        if (name === 'TRUE' || name === 'FALSE') {
          tokens.push({ type: 'boolean', value: name === 'TRUE' })
        } else {
          // Could be a cell address, range, or function name
          tokens.push({ type: 'name', value: name })
        }
        continue
      }

      // Unknown character
      i++
    }

    return tokens
  }

  currentToken() {
    if (this.tokenIndex < this.tokens.length) {
      return this.tokens[this.tokenIndex]
    }
    return null
  }

  consumeToken() {
    this.tokenIndex++
  }

  expect(value) {
    const token = this.currentToken()
    if (!token || token.type !== 'operator' || token.value !== value) {
      return false
    }
    this.consumeToken()
    return true
  }

  parse() {
    try {
      const result = this.parseExpr()
      return result
    } catch (e) {
      return { type: 'error', value: '#ERR!' }
    }
  }

  parseDeps() {
    try {
      this.parseExpr()
      return Array.from(this.deps)
    } catch (e) {
      return Array.from(this.deps)
    }
  }

  parseExpr() {
    return this.parseComparison()
  }

  parseComparison() {
    let left = this.parseAdditive()

    while (true) {
      const token = this.currentToken()
      if (!token || token.type !== 'operator') {
        break
      }

      const op = token.value
      if (['=', '<>', '<', '<=', '>', '>='].includes(op)) {
        this.consumeToken()
        const right = this.parseAdditive()

        // Check for error in left or right
        if (left.type === 'error') {
          // left error wins
          break
        }
        if (right.type === 'error') {
          left = right
          break
        }

        left = this.applyComparison(left, op, right)
      } else {
        break
      }
    }

    return left
  }

  parseAdditive() {
    let left = this.parseMultiplicative()

    while (true) {
      const token = this.currentToken()
      if (!token || token.type !== 'operator') {
        break
      }

      const op = token.value
      if (op === '+' || op === '-') {
        this.consumeToken()
        const right = this.parseMultiplicative()

        if (left.type === 'error') {
          break
        }
        if (right.type === 'error') {
          left = right
          break
        }

        left = this.applyArithmetic(left, op, right)
      } else {
        break
      }
    }

    return left
  }

  parseMultiplicative() {
    let left = this.parsePower()

    while (true) {
      const token = this.currentToken()
      if (!token || token.type !== 'operator') {
        break
      }

      const op = token.value
      if (op === '*' || op === '/') {
        this.consumeToken()
        const right = this.parsePower()

        if (left.type === 'error') {
          break
        }
        if (right.type === 'error') {
          left = right
          break
        }

        left = this.applyArithmetic(left, op, right)
      } else {
        break
      }
    }

    return left
  }

  parsePower() {
    let left = this.parseUnary()

    const token = this.currentToken()
    if (token && token.type === 'operator' && token.value === '^') {
      this.consumeToken()
      const right = this.parsePower()  // Right-associative

      if (left.type === 'error') {
        return left
      }
      if (right.type === 'error') {
        return right
      }

      return this.applyArithmetic(left, '^', right)
    }

    return left
  }

  parseUnary() {
    const token = this.currentToken()
    if (token && token.type === 'operator' && (token.value === '+' || token.value === '-')) {
      const op = token.value
      this.consumeToken()
      const expr = this.parseUnary()

      if (expr.type === 'error') {
        return expr
      }

      if (op === '-') {
        if (expr.type === 'number') {
          return { type: 'number', value: -expr.value }
        } else if (expr.type === 'boolean') {
          return { type: 'number', value: -(expr.value ? 1 : 0) }
        } else if (expr.type === 'text') {
          return { type: 'error', value: '#VALUE!' }
        } else {
          return expr
        }
      } else {
        // Unary +
        if (expr.type === 'number') {
          return expr
        } else if (expr.type === 'boolean') {
          return { type: 'number', value: expr.value ? 1 : 0 }
        } else if (expr.type === 'text') {
          return { type: 'error', value: '#VALUE!' }
        } else {
          return expr
        }
      }
    }

    return this.parsePrimary()
  }

  parsePrimary() {
    const token = this.currentToken()

    if (!token) {
      return { type: 'error', value: '#ERR!' }
    }

    // Number literal
    if (token.type === 'number') {
      this.consumeToken()
      return { type: 'number', value: token.value }
    }

    // Boolean literal
    if (token.type === 'boolean') {
      this.consumeToken()
      return { type: 'boolean', value: token.value }
    }

    // Parenthesized expression
    if (token.type === 'operator' && token.value === '(') {
      this.consumeToken()
      const expr = this.parseExpr()
      if (!this.expect(')')) {
        return { type: 'error', value: '#ERR!' }
      }
      return expr
    }

    // Name (cell address, range, or function call)
    if (token.type === 'name') {
      const name = token.value
      this.consumeToken()

      // Check for function call
      const nextToken = this.currentToken()
      if (nextToken && nextToken.type === 'operator' && nextToken.value === '(') {
        return this.parseFunctionCall(name)
      }

      // Check for range (address:address)
      if (this.isValidAddress(name)) {
        const nextToken2 = this.currentToken()
        if (nextToken2 && nextToken2.type === 'operator' && nextToken2.value === ':') {
          this.consumeToken()
          const nextName = this.currentToken()
          if (!nextName || nextName.type !== 'name') {
            return { type: 'error', value: '#ERR!' }
          }
          const rangeTo = nextName.value
          this.consumeToken()

          if (!this.isValidAddress(rangeTo)) {
            // Addresses in range must be valid
            return { type: 'error', value: '#ERR!' }
          }

          // Ranges not allowed in this context (only in function arguments)
          return { type: 'error', value: '#ERR!' }
        }

        // It's a cell address
        this.deps.add(name)
        const value = this.evaluator.evaluateCell(name)
        return value
      }

      // Invalid address or name
      return { type: 'error', value: '#NAME?' }
    }

    return { type: 'error', value: '#ERR!' }
  }

  parseFunctionCall(funcName) {
    this.expect('(')
    const args = []

    while (true) {
      const token = this.currentToken()
      if (token && token.type === 'operator' && token.value === ')') {
        break
      }

      // Parse argument (could be a range)
      const arg = this.parseFunctionArg()
      args.push(arg)

      const nextToken = this.currentToken()
      if (!nextToken) {
        return { type: 'error', value: '#ERR!' }
      }

      if (nextToken.type === 'operator') {
        if (nextToken.value === ',') {
          this.consumeToken()
          continue
        } else if (nextToken.value === ')') {
          break
        }
      }

      return { type: 'error', value: '#ERR!' }
    }

    if (!this.expect(')')) {
      return { type: 'error', value: '#ERR!' }
    }

    return this.applyFunction(funcName, args)
  }

  parseFunctionArg() {
    // For function arguments, ranges are allowed
    const token = this.currentToken()

    if (!token) {
      return { type: 'error', value: '#ERR!' }
    }

    // Try to parse as a range first if it starts with a name
    if (token.type === 'name') {
      const name = token.value

      if (this.isValidAddress(name)) {
        this.consumeToken()
        this.deps.add(name)

        const nextToken = this.currentToken()
        if (nextToken && nextToken.type === 'operator' && nextToken.value === ':') {
          this.consumeToken()
          const nextName = this.currentToken()

          if (!nextName || nextName.type !== 'name') {
            return { type: 'error', value: '#ERR!' }
          }

          const rangeTo = nextName.value
          this.consumeToken()

          if (!this.isValidAddress(rangeTo)) {
            return { type: 'error', value: '#ERR!' }
          }

          // Return range as a special type
          return { type: 'range', from: name, to: rangeTo }
        }

        // Just a single cell
        const value = this.evaluator.evaluateCell(name)
        return value
      }
    }

    // Parse as a normal expression
    return this.parseExpr()
  }

  isValidAddress(name) {
    const match = name.match(/^([A-Z]{1,2})(\d{1,3})$/)
    if (!match) {
      return false
    }
    const row = parseInt(match[2])
    return row >= 1 && row <= 999
  }

  applyFunction(funcName, args) {
    switch (funcName) {
      case 'SUM':
        return this.builtinSUM(args)
      case 'MIN':
        return this.builtinMIN(args)
      case 'MAX':
        return this.builtinMAX(args)
      case 'COUNT':
        return this.builtinCOUNT(args)
      case 'AVG':
        return this.builtinAVG(args)
      case 'ABS':
        return this.builtinABS(args)
      case 'IF':
        return this.builtinIF(args)
      default:
        return { type: 'error', value: '#NAME?' }
    }
  }

  builtinSUM(args) {
    if (args.length === 0) {
      return { type: 'error', value: '#ERR!' }
    }

    let sum = 0
    for (const arg of args) {
      const val = this.getRangeOrValue(arg)
      for (const v of val) {
        if (v.type === 'error') {
          return v
        }
        const num = this.toNumber(v)
        if (num.type === 'error') {
          return num
        }
        sum += num.value
      }
    }

    const result = sum
    if (!isFinite(result)) {
      return { type: 'error', value: '#DIV/0!' }
    }
    return { type: 'number', value: result }
  }

  builtinMIN(args) {
    if (args.length === 0) {
      return { type: 'error', value: '#ERR!' }
    }

    let min = Infinity
    for (const arg of args) {
      const val = this.getRangeOrValue(arg)
      for (const v of val) {
        if (v.type === 'error') {
          return v
        }
        const num = this.toNumber(v)
        if (num.type === 'error') {
          return num
        }
        min = Math.min(min, num.value)
      }
    }

    if (!isFinite(min)) {
      return { type: 'error', value: '#DIV/0!' }
    }
    return { type: 'number', value: min }
  }

  builtinMAX(args) {
    if (args.length === 0) {
      return { type: 'error', value: '#ERR!' }
    }

    let max = -Infinity
    for (const arg of args) {
      const val = this.getRangeOrValue(arg)
      for (const v of val) {
        if (v.type === 'error') {
          return v
        }
        const num = this.toNumber(v)
        if (num.type === 'error') {
          return num
        }
        max = Math.max(max, num.value)
      }
    }

    if (!isFinite(max)) {
      return { type: 'error', value: '#DIV/0!' }
    }
    return { type: 'number', value: max }
  }

  builtinCOUNT(args) {
    if (args.length === 0) {
      return { type: 'error', value: '#ERR!' }
    }

    let count = 0
    for (const arg of args) {
      const val = this.getRangeOrValue(arg)
      for (const v of val) {
        if (v.type === 'error') {
          return v
        }
        if (v.type === 'number') {
          count++
        }
      }
    }

    return { type: 'number', value: count }
  }

  builtinAVG(args) {
    if (args.length === 0) {
      return { type: 'error', value: '#ERR!' }
    }

    let sum = 0
    let count = 0
    for (const arg of args) {
      const val = this.getRangeOrValue(arg)
      for (const v of val) {
        if (v.type === 'error') {
          return v
        }
        const num = this.toNumber(v)
        if (num.type === 'error') {
          return num
        }
        sum += num.value
        count++
      }
    }

    if (count === 0) {
      return { type: 'error', value: '#DIV/0!' }
    }

    const result = sum / count
    if (!isFinite(result)) {
      return { type: 'error', value: '#DIV/0!' }
    }
    return { type: 'number', value: result }
  }

  builtinABS(args) {
    if (args.length !== 1) {
      return { type: 'error', value: '#ERR!' }
    }

    const val = this.getRangeOrValue(args[0])
    if (val.length === 0) {
      return { type: 'error', value: '#ERR!' }
    }

    const v = val[0]
    if (v.type === 'error') {
      return v
    }

    const num = this.toNumber(v)
    if (num.type === 'error') {
      return num
    }

    const result = Math.abs(num.value)
    if (!isFinite(result)) {
      return { type: 'error', value: '#DIV/0!' }
    }
    return { type: 'number', value: result }
  }

  builtinIF(args) {
    if (args.length !== 3) {
      return { type: 'error', value: '#ERR!' }
    }

    const condVal = args[0]
    if (condVal.type === 'error') {
      return condVal
    }

    const cond = this.toBoolean(condVal)

    if (cond) {
      return args[1]
    } else {
      return args[2]
    }
  }

  getRangeOrValue(arg) {
    if (arg.type === 'range') {
      return this.expandRange(arg.from, arg.to)
    } else {
      return [arg]
    }
  }

  expandRange(from, to) {
    const fromMatch = from.match(/^([A-Z]{1,2})(\d{1,3})$/)
    const toMatch = to.match(/^([A-Z]{1,2})(\d{1,3})$/)

    const fromCol = fromMatch[1]
    const fromRow = parseInt(fromMatch[2])
    const toCol = toMatch[1]
    const toRow = parseInt(toMatch[2])

    const colStart = this.colToNum(fromCol)
    const colEnd = this.colToNum(toCol)
    const rowStart = Math.min(fromRow, toRow)
    const rowEnd = Math.max(fromRow, toRow)

    const cells = []
    for (let col = Math.min(colStart, colEnd); col <= Math.max(colStart, colEnd); col++) {
      for (let row = rowStart; row <= rowEnd; row++) {
        const address = this.numToCol(col) + row
        this.deps.add(address)
        cells.push(this.evaluator.evaluateCell(address))
      }
    }

    return cells
  }

  colToNum(col) {
    let num = 0
    for (let i = 0; i < col.length; i++) {
      num = num * 26 + (col.charCodeAt(i) - 'A'.charCodeAt(0) + 1)
    }
    return num
  }

  numToCol(num) {
    let col = ''
    while (num > 0) {
      col = String.fromCharCode((num - 1) % 26 + 'A'.charCodeAt(0)) + col
      num = Math.floor((num - 1) / 26)
    }
    return col
  }

  toNumber(val) {
    if (val.type === 'number') {
      return val
    }
    if (val.type === 'boolean') {
      return { type: 'number', value: val.value ? 1 : 0 }
    }
    if (val.type === 'text') {
      return { type: 'error', value: '#VALUE!' }
    }
    return val
  }

  toBoolean(val) {
    if (val.type === 'boolean') {
      return val.value
    }
    if (val.type === 'number') {
      return val.value !== 0
    }
    // text and error are falsy in boolean context
    return false
  }

  applyArithmetic(left, op, right) {
    const leftNum = this.toNumber(left)
    if (leftNum.type === 'error') {
      return leftNum
    }

    const rightNum = this.toNumber(right)
    if (rightNum.type === 'error') {
      return rightNum
    }

    const l = leftNum.value
    const r = rightNum.value

    let result
    switch (op) {
      case '+':
        result = l + r
        break
      case '-':
        result = l - r
        break
      case '*':
        result = l * r
        break
      case '/':
        if (r === 0) {
          return { type: 'error', value: '#DIV/0!' }
        }
        result = l / r
        break
      case '^':
        result = Math.pow(l, r)
        break
      default:
        return { type: 'error', value: '#ERR!' }
    }

    if (!isFinite(result)) {
      return { type: 'error', value: '#DIV/0!' }
    }

    return { type: 'number', value: result }
  }

  applyComparison(left, op, right) {
    // For comparisons, we compare numbers numerically, texts by code point, booleans by false < true
    // Across kinds: every number < every text < every boolean

    const leftType = left.type
    const rightType = right.type
    let leftVal = left.value
    let rightVal = right.value

    // Convert to comparable values
    let leftNum = null
    let rightNum = null

    if (leftType === 'number') {
      leftNum = 0
    } else if (leftType === 'text') {
      leftNum = 1
    } else if (leftType === 'boolean') {
      leftNum = 2
    }

    if (rightType === 'number') {
      rightNum = 0
    } else if (rightType === 'text') {
      rightNum = 1
    } else if (rightType === 'boolean') {
      rightNum = 2
    }

    // Same type comparisons
    if (leftType === rightType) {
      if (leftType === 'number') {
        return this.compareNumbers(leftVal, rightVal, op)
      } else if (leftType === 'text') {
        return this.compareTexts(leftVal, rightVal, op)
      } else if (leftType === 'boolean') {
        return this.compareBooleans(leftVal, rightVal, op)
      }
    }

    // Cross-type comparison
    if (op === '=') {
      return { type: 'boolean', value: false }
    } else if (op === '<>') {
      return { type: 'boolean', value: true }
    }

    // For ordering comparisons with different types
    switch (op) {
      case '<':
        return { type: 'boolean', value: leftNum < rightNum }
      case '<=':
        return { type: 'boolean', value: leftNum <= rightNum }
      case '>':
        return { type: 'boolean', value: leftNum > rightNum }
      case '>=':
        return { type: 'boolean', value: leftNum >= rightNum }
    }

    return { type: 'error', value: '#ERR!' }
  }

  compareNumbers(left, right, op) {
    let result
    switch (op) {
      case '=':
        result = left === right
        break
      case '<>':
        result = left !== right
        break
      case '<':
        result = left < right
        break
      case '<=':
        result = left <= right
        break
      case '>':
        result = left > right
        break
      case '>=':
        result = left >= right
        break
      default:
        return { type: 'error', value: '#ERR!' }
    }
    return { type: 'boolean', value: result }
  }

  compareTexts(left, right, op) {
    const cmp = left.localeCompare(right)
    let result
    switch (op) {
      case '=':
        result = cmp === 0
        break
      case '<>':
        result = cmp !== 0
        break
      case '<':
        result = cmp < 0
        break
      case '<=':
        result = cmp <= 0
        break
      case '>':
        result = cmp > 0
        break
      case '>=':
