if (token.type === 'name') {
  const name = token.value

  // Check if it looks like an address
  if (this.looksLikeAddress(name)) {
    if (!this.isValidAddress(name)) {
      // Looks like address but outside range
      return { type: 'error', value: '#REF!' }
    }

    this.consumeToken()
    this.deps.add(name)

